def pagerank(graph, damping=0.85, num_iterations=100):
    """
    Compute PageRank scores via power iteration.

    graph: dict mapping each page node -> list of its outlink target nodes.
    damping: probability a "random surfer" follows an outlink (vs. teleporting).
    num_iterations: number of power-iteration rounds to run.
    """
    N = len(graph)
    ranks = {node: 1 / N for node in graph}

    for _ in range(num_iterations):
        # Seed this round with only the teleport/base term.
        new_ranks = {node: (1 - damping) / N for node in graph}

        # Distribute each node's current rank across its outlinks.
        for u in graph:
            out = graph[u]
            if len(out) == 0:
                # Dangling node (no outlinks) — nothing to distribute.
                continue
            share = damping * ranks[u] / len(out)
            for v in out:
                new_ranks[v] += share

        ranks = new_ranks

    return ranks
